34	public class BindingErrorsResponse {
35	
36	    public BindingErrorsResponse() {
37	        this(null);
38	    }
39	
40	    public BindingErrorsResponse(Integer id) {
41	        this(null, id);
42	    }
43	
44	    public BindingErrorsResponse(Integer pathId, Integer bodyId) {
45	        boolean onlyBodyIdSpecified = pathId == null && bodyId != null;
46	        if (onlyBodyIdSpecified) {
47	            addBodyIdError(bodyId, "must not be specified");
48	        }
49	        boolean bothIdsSpecified = pathId != null && bodyId != null;
50	        if (bothIdsSpecified && !pathId.equals(bodyId)) {
51	            addBodyIdError(bodyId, "does not match pathId: %d".formatted(pathId));
52	        }
53	    }
54	
55	    private void addBodyIdError(Integer bodyId, String message) {
56	        BindingError error = new BindingError();
57	        error.setObjectName("body");
58	        error.setFieldName("id");
59	        error.setFieldValue(bodyId.toString());
60	        error.setErrorMessage(message);
61	        addError(error);
62	    }
63	
64		private final List<BindingError> bindingErrors = new ArrayList<>();
65	
66		public void addError(BindingError bindingError) {
67			this.bindingErrors.add(bindingError);
68		}
69	
70		public void addAllErrors(BindingResult bindingResult) {
71			for (FieldError fieldError : bindingResult.getFieldErrors()) {
72				BindingError error = new BindingError();
73				error.setObjectName(fieldError.getObjectName());
74				error.setFieldName(fieldError.getField());
75				error.setFieldValue(String.valueOf(fieldError.getRejectedValue()));
76				error.setErrorMessage(fieldError.getDefaultMessage());
77				addError(error);
78			}
79		}
80	
81		public String toJSON() {
82			ObjectMapper mapper = JsonMapper.builder()
83	                .changeDefaultVisibility(v -> v.withFieldVisibility(Visibility.ANY))
84	                    .build();
85			String errorsAsJSON = "";
86			try {
87				errorsAsJSON = mapper.writeValueAsString(bindingErrors);
88			} catch (JacksonException e) {
89				e.printStackTrace();
90			}
91			return errorsAsJSON;
92		}
93	
94		@Override
95		public String toString() {
96			return "BindingErrorsResponse [bindingErrors=" + bindingErrors + "]";
97		}
